def montar_prompt(mensagem, papel=True, categorias=True,
                  formato_json=True, exemplos=()):
    partes = []
    if papel: partes.append("Você é um assistente de triagem ...")
    ...   # tarefa, categorias, exemplos (trecho resumido)
    partes.append('Responda apenas com JSON: {"intencao": ..., "evidencia": ...}')
    partes.append(f"Mensagem: <<<{mensagem}>>>")
    return "\n\n".join(partes)

def montar_prompt_documentos(pergunta, documentos):
    corpo = "
".join(f'<documento id="{i}">
{t}
</documento>'
                      for i, t in documentos)
    return ("Responda usando APENAS os documentos abaixo. Cite o id. "
            "Se a resposta não estiver nos documentos, responda "
            "exatamente: não consta.

"
            f"{corpo}

Pergunta: {pergunta}
Resposta:")

def citacao_existe(citacao, documento):
    return normalizar(citacao) in normalizar(documento)

def conferir_calculo(atraso_dias, exemplares, multa_dia,
                     total_informado, tol=0.01):
    esperado = atraso_dias * exemplares * multa_dia
    return abs(esperado - total_informado) <= tol, esperado
